          "definition": "يُقصد بـ (مقدمة في Core Modules) أحد المفاهيم المحورية في مسار التعامل مع نظام التشغيل ضمن بيئة Node.js؛ حيث يوفر للمهندس الأدوات المعمارية والبرمجية لمعالجة تدفقات البيانات وتقديم أداء عالي الاستقرار في بيئات الإنتاج الحية.",
